/**
 * dsh-provider-usage — 按天分片 JSONL 历史存储（v2）。
 *
 * 取代旧 v3 多文件 JSON 桶格式。优点：
 * - append 为 O(1)（appendFile），无读-改-写竞态
 * - 留存清理 = 删除过期日文件，非全量重写
 * - 进程崩溃只损失当次未写完的一行
 *
 * 目录结构：historyDir/<safe(provider)>/<safe(name)>/YYYY-MM-DD.jsonl
 */
import { randomBytes } from "node:crypto";
import { appendFile, mkdir, readFile, readdir, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { safeSegment } from "../../shared/interface.ts";

/** 历史条目（JSONL 行）。 */
export interface HistoryEntry {
  time: number;
  data: Record<string, unknown>;
}

/** 按天分片 JSONL 历史存储。 */
export class HistoryStore {
  private readonly root: string;
  private readonly maxAgeMs: number;
  private readonly maxSizeBytes: number;
  /**
   * 同目标日文件的写链：writeDirect 并发同文件时 rename 先后无保证，串行防旧数据盖新数据。
   * 实例级（随 HistoryStore 实例生灭，无模块级可变状态——forbid-module-state-src 零新增）。
   */
  private readonly writeChains = new Map<string, Promise<void>>();

  constructor(opts: { root: string; maxAgeMs?: number; maxSizeBytes?: number }) {
    this.root = opts.root;
    this.maxAgeMs = opts.maxAgeMs ?? 30 * 24 * 60 * 60 * 1000; // 30 天
    this.maxSizeBytes = opts.maxSizeBytes ?? 20 * 1024 * 1024; // 20MB
  }

  /**
   * 适配器目录（provider/name 均安全化）。safeSegment 保留点号（`a.b` 合法），
   * 故 `.`/`..` 另收敛为 `unknown`——否则 join 穿透隔离根（包 AGENTS.md 落盘
   * basename 化纪律）。收敛放本域（shared 的 safeSegment 是稳定公共契约，
   * 单测钉死 `a.b_c` 形态，不在本域改它）。
   */
  private dirOf(provider: string, name: string): string {
    return join(this.root, dirSegment(provider), dirSegment(name));
  }

  /** 当日文件名。 */
  private fileOf(provider: string, name: string, time: number): string {
    const d = new Date(time);
    const day = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    return join(this.dirOf(provider, name), `${day}.jsonl`);
  }

  /** 追加一条（O(1) appendFile；prune 已移出热路径改独立定时器）。 */
  async append(provider: string, name: string, entry: HistoryEntry): Promise<void> {
    const file = this.fileOf(provider, name, entry.time);
    await mkdir(this.dirOf(provider, name), { recursive: true, mode: 0o700 });
    await appendFile(file, `${JSON.stringify(entry)}\n`, { encoding: "utf8", mode: 0o600 });
  }

  /** 读取某日的条目（文件不存在返回空；并发删文件竞态容错返回空）。 */
  async readDay(provider: string, name: string, time: number): Promise<HistoryEntry[]> {
    const file = this.fileOf(provider, name, time);
    let raw: string;
    try {
      raw = await readFile(file, "utf8");
    } catch {
      // ENOENT 容错——prune 在 existsSync 与 readFile 之间删掉过期文件时
      // 返回空而非抛异常（此前会导致 /history 路由 500 崩溃路径）。
      return [];
    }
    return parseJsonl(raw);
  }

  /**
   * 按时间范围查询（只扫 range 覆盖的天数文件）。
   *
   * **全量返回**：range 内所有匹配条目（时间升序），不做 limit 截断——
   * 历史必须包含最新采样（面板卡片头与胶囊实时数据一致性依赖于此）。
   * 响应体积可控：formatPanel 渲染为 HTML 后只含图表卡片，不透传原始数组。
   */
  async query(
    provider: string,
    name: string,
    range: { start: number; end: number },
  ): Promise<{ entries: HistoryEntry[] }> {
    const entries: HistoryEntry[] = [];
    const promises: Promise<HistoryEntry[]>[] = [];
    // range 覆盖的天列表（升序），并发读取
    for (let day = startOfDay(range.start); day <= startOfDay(range.end); day += 86400000) {
      promises.push(
        this.readDay(provider, name, day).then((dayEntries) =>
          dayEntries.filter((e) => e.time >= range.start && e.time <= range.end),
        ),
      );
    }
    const results = await Promise.all(promises);
    for (const dayEntries of results) {
      entries.push(...dayEntries);
    }
    // 稳定排序防御乱序采样（append 天然近似有序）
    entries.sort((a, b) => a.time - b.time);
    return { entries };
  }

  /** 获取最后一条（读最后一天文件的尾行 try-parse，失败返回 null）。 */
  async last(provider: string, name: string): Promise<HistoryEntry | null> {
    const dir = this.dirOf(provider, name);
    let files: string[];
    try {
      files = await readdir(dir);
    } catch {
      return null;
    }
    const jsonlFiles = files.filter((f) => f.endsWith(".jsonl")).sort();
    for (let i = jsonlFiles.length - 1; i >= 0; i--) {
      const file = join(dir, jsonlFiles[i]);
      try {
        const raw = await readFile(file, "utf8");
        const lines = raw.trimEnd().split("\n");
        for (let j = lines.length - 1; j >= 0; j--) {
          try {
            const entry = JSON.parse(lines[j]) as HistoryEntry;
            if (
              typeof entry?.time === "number" &&
              typeof entry.data === "object" &&
              entry.data !== null
            ) {
              return entry;
            }
          } catch {
            continue; // 坏行跳过
          }
        }
      } catch {
        continue; // 文件读取失败跳过
      }
    }
    return null;
  }

  /** 留存清理：删过期日文件 + 总大小超限时从最旧文件逐个删。 */
  async maybePrune(provider: string, name: string): Promise<void> {
    const dir = this.dirOf(provider, name);
    let files: string[];
    try {
      files = await readdir(dir);
    } catch {
      return;
    }
    const cutoff = Date.now() - this.maxAgeMs;
    const jsonlFiles = files.filter((f) => f.endsWith(".jsonl")).sort();
    // 1. 删过期文件（按文件名日期）
    for (const f of jsonlFiles) {
      const dayMs = Date.parse(f.slice(0, 10));
      if (Number.isFinite(dayMs) && dayMs < cutoff) {
        try {
          await rm(join(dir, f), { force: true });
        } catch {
          /* 忽略 */
        }
      }
    }
    // 2. 总大小超限：从最旧文件逐个删（保留最后 1 个文件，防清零）
    const remaining = jsonlFiles.filter((f) => {
      const dayMs = Date.parse(f.slice(0, 10));
      return !(Number.isFinite(dayMs) && dayMs < cutoff);
    });
    let total = 0;
    for (const f of remaining) {
      try {
        const stat = await import("node:fs/promises").then((m) => m.stat(join(dir, f)));
        total += stat.size;
      } catch {
        /* 忽略 */
      }
    }
    while (total > this.maxSizeBytes && remaining.length > 1) {
      const oldest = remaining.shift();
      if (oldest === undefined) break;
      try {
        const stat = await import("node:fs/promises").then((m) => m.stat(join(dir, oldest)));
        total -= stat.size;
        await rm(join(dir, oldest), { force: true });
      } catch {
        /* 忽略 */
      }
    }
  }

  /**
   * 全树留存清理（独立定时器调用，替代 append 热路径内联）。
   *
   * 扫描 root 下全部 provider/name 目录，对每目录执行 retention 清理
   * （删过期日文件 + 超限时从最旧删）。**语义锁死：只按 retention 规则删除
   * 过期/超限文件，绝不删除未注册目录的数据**——用户回切适配器仍需读取。
   *
   * 注：maxSizeBytes 语义为「单 (provider,name) 目录上界」（与 append 时代
   * 的 maybePrune 一致）；全局磁盘上界 = 目录数 × 上限。停用适配器的孤儿
   * 目录同样受 retention 清理（其过期/超限文件会被删，数据文件本身保留）。
   */
  async pruneAll(): Promise<void> {
    let providers: string[];
    try {
      providers = await readdir(this.root);
    } catch {
      return;
    }
    for (const provider of providers) {
      if (provider.startsWith(".") || provider === "legacy-v3.bak") continue;
      // trend 目录（会话用量趋势明细/聚合分片）不归 HistoryStore 的 maxAgeDays/
      // maxSizeMB 管——其留存周期独立为 trendRetentionDays（默认 180 天），由
      // TrendTracker.prune() 按自身 cutoff 清理。trend 分片文件名 YYYY-MM-DD.jsonl
      // 恰好命中下方 Date.parse 日期启发，漏排会被 30 天默认 retention 静默误删。
      if (provider === "trend") continue;
      const pdir = join(this.root, provider);
      let names: string[];
      try {
        names = await readdir(pdir);
      } catch {
        continue;
      }
      for (const name of names) {
        if (name.startsWith(".")) continue;
        await this.maybePrune(provider, name);
      }
    }
  }

  /** 导出全部数据（调试/割接用）。 */
  async exportAll(provider: string, name: string): Promise<HistoryEntry[]> {
    const dir = this.dirOf(provider, name);
    let files: string[];
    try {
      files = await readdir(dir);
    } catch {
      return [];
    }
    const out: HistoryEntry[] = [];
    for (const f of files.filter((x) => x.endsWith(".jsonl")).sort()) {
      try {
        out.push(...parseJsonl(await readFile(join(dir, f), "utf8")));
      } catch {
        /* 忽略 */
      }
    }
    return out;
  }

  /**
   * 割接：原子写一份文件（0600，tmp + rename，失败清理临时名后上抛原错误）。
   * 供迁移工具把旧 v3 数据拷入新格式时使用。临时名带 pid + 随机串（同毫秒并发不撞名），
   * 同文件并发经实例级写链串行（rename 先后无保证，串行防旧数据盖新数据）。
   */
  async writeDirect(
    provider: string,
    name: string,
    day: number,
    entries: HistoryEntry[],
  ): Promise<void> {
    if (entries.length === 0) return;
    const file = this.fileOf(provider, name, day);
    const previous = this.writeChains.get(file) ?? Promise.resolve();
    const next = previous.then(
      () => this.writeOnce(file, provider, name, entries),
      () => this.writeOnce(file, provider, name, entries),
    );
    this.writeChains.set(file, next);
    return next.finally(() => {
      if (this.writeChains.get(file) === next) this.writeChains.delete(file);
    });
  }

  /** writeDirect 单次落盘：建目录（0700）+ 写临时名（0600）+ rename；失败清临时名。 */
  private async writeOnce(
    file: string,
    provider: string,
    name: string,
    entries: HistoryEntry[],
  ): Promise<void> {
    await mkdir(this.dirOf(provider, name), { recursive: true, mode: 0o700 });
    const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString("hex")}.tmp`;
    const text = entries.map((e) => JSON.stringify(e)).join("\n") + "\n";
    try {
      await writeFile(tmp, text, { encoding: "utf8", mode: 0o600 });
      await rename(tmp, file);
    } catch (e) {
      await rm(tmp, { force: true }).catch(() => undefined);
      throw e;
    }
  }
}

/** 单目录段收敛：safeSegment 后再拒收 `.`/`..`（join 穿透），空回落与 safeSegment 同口径。 */
function dirSegment(s: string): string {
  const seg = safeSegment(s);
  return seg === "." || seg === ".." ? "unknown" : seg;
}

/** 解析 JSONL 文本为条目数组（跳过坏行）。 */
export function parseJsonl(raw: string): HistoryEntry[] {
  const out: HistoryEntry[] = [];
  for (const line of raw.split("\n")) {
    if (line.trim() === "") continue;
    try {
      const entry = JSON.parse(line) as HistoryEntry;
      if (
        typeof entry?.time === "number" &&
        typeof entry.data === "object" &&
        entry.data !== null
      ) {
        out.push(entry);
      }
    } catch {
      continue; // 坏行跳过
    }
  }
  return out;
}

/** 某天 00:00:00 的时间戳。 */
export function startOfDay(time: number): number {
  const d = new Date(time);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

/** 目录结构推导（探测用：返回已有 provider/name 列表）。 */
export async function listAdapters(
  root: string,
): Promise<Array<{ provider: string; name: string }>> {
  let providers: string[];
  try {
    providers = await readdir(root);
  } catch {
    return [];
  }
  const out: Array<{ provider: string; name: string }> = [];
  for (const p of providers) {
    try {
      const names = await readdir(join(root, p));
      for (const n of names) out.push({ provider: p, name: n });
    } catch {
      /* 忽略 */
    }
  }
  return out;
}

// ------------------------------------------------------------------ v3 旧格式迁移

/** v3 桶文件头（历史多文件格式，读取后迁移为按天分片 JSONL）。 */
interface LegacyV3Bucket {
  provider?: string;
  adapterId?: string;
  columns?: Array<{ key: string; name: string; limit?: number }>;
  samples?: Array<Array<number | null>>;
}

/**
 * 已知的「裸数值列」（v3 percent 语义不适用、值为原始量纲的列）。
 * 迁移时这些列产出裸值（如 rjk 的 balance 余额元），格式函数可直接用。
 */
const RAW_VALUE_COLUMNS: ReadonlySet<string> = new Set(["balance"]);

/**
 * 把 v3 桶样本序列翻译为新 JSONL 的 data 对象。
 *
 * 内置 opencode-go 桶列序 = 三窗口 [rolling, weekly, monthly]，逐列装配
 * `{key: {percent}}` 窗口对象；RAW_VALUE_COLUMNS 内的列（如 balance）产出
 * `{key: 裸值}`；其余列按列声明通用装配 `{colNN: value}`。
 */
export function legacySampleToData(
  columns: LegacyV3Bucket["columns"],
  sample: Array<number | null>,
): Record<string, unknown> {
  const data: Record<string, unknown> = {};
  const width = sample.length - 1;
  for (let c = 0; c < width; c += 1) {
    const col = columns?.[c];
    const val = sample[c + 1];
    if (col !== undefined && typeof col.key === "string") {
      if (RAW_VALUE_COLUMNS.has(col.key)) {
        // 余额型裸数值列：原始量纲直出
        data[col.key] = typeof val === "number" ? val : null;
      } else {
        // 内置三窗口列：percent 语义
        data[col.key] = { percent: typeof val === "number" ? val : null };
      }
    } else {
      data[`col${c + 1}`] = val;
    }
  }
  return data;
}

/**
 * 启动时迁移旧 v3 多文件桶到按天分片 JSONL。
 *
 * 扫描 `<root>/history/<provider>/<adapterId>.json`：
 * - 读取每个桶 → 逐采样点调 store.writeDirect 写到对应日文件；
 * - 迁移成功后旧文件重命名为 `.bak` 保留（不删除，由用户清理）；
 * - 幂等：`.bak` 文件不再扫描；失败保留原文件下次重试。
 * @returns 迁移的采样点数（诊断用）。
 */
async function readLegacyEntries(
  pdir: string,
  file: string,
): Promise<{ adapterId: string; entries: HistoryEntry[] } | null> {
  const adapterId = file.slice(0, -5);
  let raw: string;
  try {
    raw = await readFile(join(pdir, file), "utf8");
  } catch {
    return null;
  }
  let bucket: LegacyV3Bucket;
  try {
    bucket = JSON.parse(raw) as LegacyV3Bucket;
  } catch {
    return null;
  }
  if (!Array.isArray(bucket.samples) || bucket.samples.length === 0) return null;
  const cols = bucket.columns;
  const entries: HistoryEntry[] = [];
  for (const sample of bucket.samples) {
    if (!Array.isArray(sample) || sample.length < 2) continue;
    const ts = Number(sample[0]);
    if (!Number.isFinite(ts)) continue;
    entries.push({ time: ts, data: legacySampleToData(cols, sample) });
  }
  return { adapterId, entries };
}
async function writeDayGroups(
  store: HistoryStore,
  provider: string,
  adapterId: string,
  entries: HistoryEntry[],
): Promise<boolean> {
  const byDay = new Map<number, HistoryEntry[]>();
  for (const entry of entries) {
    const day = startOfDay(entry.time);
    const list = byDay.get(day);
    if (list === undefined) byDay.set(day, [entry]);
    else list.push(entry);
  }
  for (const pair of byDay) {
    try {
      await store.writeDirect(provider, adapterId, pair[0], pair[1]);
    } catch {
      return false;
    }
  }
  return true;
}
async function migrateProvider(
  pdir: string,
  provider: string,
  store: HistoryStore,
): Promise<number> {
  let migrated = 0;
  let files: string[];
  try {
    files = await readdir(pdir);
  } catch {
    return migrated;
  }
  for (const file of files) {
    if (!file.endsWith(".json")) continue; // .bak 与其它格式跳过
    const loaded = await readLegacyEntries(pdir, file);
    if (loaded === null) continue;
    const adapterId = loaded.adapterId;
    const entries = loaded.entries;
    const ok = await writeDayGroups(store, provider, adapterId, entries);
    if (ok) {
      // 成功 → 旧文件重命名 .bak（幂等：不扫描 .bak；覆盖同名保留时间戳）
      try {
        await rename(join(pdir, file), join(pdir, `${file}.v3.bak`));
      } catch {
        /* 重命名失败保留原文件，下次重试 */
      }
      migrated += entries.length;
    }
  }
  return migrated;
}
export async function migrateLegacyV3(root: string, store: HistoryStore): Promise<number> {
  const historyDir = join(root, "history");
  let providers: string[];
  try {
    providers = await readdir(historyDir);
  } catch {
    return 0; // 无旧目录
  }
  let migrated = 0;
  for (const provider of providers) {
    const pdir = join(historyDir, provider);
    migrated += await migrateProvider(pdir, provider, store);
  }
  return migrated;
}

