    anomaliesLength = anomalies.length;
    anomalyHasSession = anomalies[0].includes("s1");
    callProvider = callsOf(emitted)[0].provider;
    callModel = callsOf(emitted)[0].model;
    // 回归：主副源一致不告警；归属缺失走副源补齐不告警（既有语义不回退）
    const silent: string[] = [];
