    try {
      const now = 2_000;
      const claimNow = now + 2;
      const route = { provider: "generic-provider", model: "generic-model" };
      const dateKeys = {
        K0: "2026-09-01",
        K1: "2026-09-02",
        K2: "2026-09-03",
      } as const;
      const inputFor = (label: keyof typeof dateKeys): ReportTaskInput => {
