/**
 * dsh-provider-usage — unit：历史数据纯函数与 opencode-go 解析辅助。
 *
 * 覆盖：parseJsonl（坏行跳过/校验）、startOfDay（时区/闰年/边界）、
 * legacySampleToData（裸值列/缺列/空值）、pickWindow（防御式解析）、
 * HistoryStore.exportAll（#82 批次 3）。
 *
 * #768 D5：被测面随域迁入 server/history（经 server/history/interface.ts
 * 直连深路径，同一引用）；本文件追加并发三条（#771 移交：大跨度 range / 同戳并发 /
 * 故障注入），全部落盘进 mkdtempSync 隔离目录，锚点相对当前（不钉墙钟）。
 */
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
console.error("EVAL-ORDER-TAG: HISTORY");
import { join } from "node:path";
import { tmpdir } from "node:os";
import { beforeAll, describe, expect, it } from "vitest";
import { pickWindow } from "../../../src/server/adapters/interface.ts";
// 白盒直连深路径（#768 B波续批）：历史存储与纯面经域门面，不走组合根转发。
import {
  HistoryStore,
  parseJsonl,
  startOfDay,
  legacySampleToData,
  migrateLegacyV3,
  type HistoryEntry,
} from "../../../src/server/history/interface.ts";
// 白盒直连深路径（#950 DST 锁定）：日界/小时/调度纯面经接缝，不走组合根转发；
// 只锁纯函数，不碰 query/retention IO，不动 history.ts:92 循环。
import { dayKey, lastNDayKeys } from "../../../src/shared/interface.ts";
import { hourOfDay } from "../../../src/server/shared/interface.ts";
import { previousClosedWindow } from "../../../src/server/schedule/interface.ts";
import { normalizeReportConfig } from "../../../src/server/config/interface.ts";
/** 无名列防御覆盖：旧 v3 列声明可缺 name（实现仅读 key），窄类型经 unknown 断言。 */
type LegacyColumns = Parameters<typeof legacySampleToData>[0];
const namelessCols = (...keys: string[]): LegacyColumns =>
  keys.map((key) => ({ key })) as unknown as LegacyColumns;

describe("parseJsonl", () => {
  it("空字符串返回空数组", () => {
    expect(parseJsonl("")).toEqual([]);
  });

  it("仅换行返回空数组", () => {
    expect(parseJsonl("\n\n")).toEqual([]);
  });

  it("两行 JSONL 解析", () => {
    expect(parseJsonl('{"time":1,"data":{}}\n{"time":2,"data":{}}')).toEqual([
      { time: 1, data: {} },
      { time: 2, data: {} },
    ]);
  });

  it("坏行跳过", () => {
    expect(parseJsonl('{"time":1,"data":{}}\nbroken\n{"time":3,"data":{}}')).toEqual([
      { time: 1, data: {} },
      { time: 3, data: {} },
    ]);
  });

  it("time 非数字行跳过", () => {
    expect(
      parseJsonl('{"time":1,"data":{}}\n{"time":"bad","data":{}}\n{"time":3,"data":{}}'),
    ).toEqual([
      { time: 1, data: {} },
      { time: 3, data: {} },
    ]);
  });

  it("data 为 null 的行跳过", () => {
    expect(parseJsonl('{"time":1,"data":null}')).toEqual([]);
  });

  it("缺 data 字段的行跳过", () => {
    expect(parseJsonl('{"time":1}')).toEqual([]);
  });

  it("尾部换行不产生空条目", () => {
    expect(parseJsonl('{"time":1,"data":{}}\n{"time":2,"data":{}}\n')).toEqual([
      { time: 1, data: {} },
      { time: 2, data: {} },
    ]);
  });
});

// startOfDay 是本地时区操作（setHours 在本地时区归零），epoch 0 在当地时区
// 的 00:00:00 对应 UTC 偏移量，此处仅断言结果可被一天整除
// startOfDay 是本地时区操作（setHours 在本地时区归零），此处断言日期分量归零。
describe("startOfDay", () => {
  describe("普通日期（本地时区）", () => {
    let s: Date;

    beforeAll(() => {
      const d = new Date(2026, 5, 15, 13, 45, 30);
      s = new Date(startOfDay(d.getTime()));
    });

    it("年不变", () => {
      expect(s.getFullYear()).toBe(2026);
    });

    it("月不变（6月）", () => {
      expect(s.getMonth()).toBe(5);
    });

    it("日不变", () => {
      expect(s.getDate()).toBe(15);
    });

    it("小时归零", () => {
      expect(s.getHours()).toBe(0);
    });

    it("分钟归零", () => {
      expect(s.getMinutes()).toBe(0);
    });
  });

  describe("闰年 2 月 29 日", () => {
    let s: Date;

    beforeAll(() => {
      const d = new Date(2024, 1, 29, 10, 0);
      s = new Date(startOfDay(d.getTime()));
    });

    it("闰年 2/29 当天零点", () => {
      expect(s.getDate()).toBe(29);
    });

    it("闰年 2 月不变", () => {
      expect(s.getMonth()).toBe(1);
    });
  });

  describe("DST 切换日（春季调快，夏季时间）", () => {
    let s: Date;

    beforeAll(() => {
      const d = new Date(2026, 2, 8, 12, 0); // 2026-03-08（美国 DST 生效日）
      s = new Date(startOfDay(d.getTime()));
    });

    it("DST 切换日当天零点", () => {
      expect(s.getDate()).toBe(8);
    });

    it("DST 切换日小时归零", () => {
      expect(s.getHours()).toBe(0);
    });
  });
});

describe("legacySampleToData", () => {
  it("balance 裸值列", () => {
    expect(
      legacySampleToData([{ key: "balance", name: "余额" }], [1787000000000, 10.1365]),
    ).toEqual({ balance: 10.1365 });
  });

  // 三窗口列
  it("三窗口 percent 列", () => {
    expect(
      legacySampleToData(namelessCols("rolling", "weekly", "monthly"), [1787000000000, 2, 1, 0]),
    ).toEqual({ rolling: { percent: 2 }, weekly: { percent: 1 }, monthly: { percent: 0 } });
  });

  // null 值在 percent 列 → null
  it("null 值 percent 列保持 null", () => {
    expect(legacySampleToData(namelessCols("rolling"), [1787000000000, null])).toEqual({
      rolling: { percent: null },
    });
  });

  // null 值在裸值列 → null
  it("null 值裸值列保持 null", () => {
    expect(legacySampleToData([{ key: "balance", name: "余额" }], [1787000000000, null])).toEqual({
      balance: null,
    });
  });

  // 无列声明 → colNN 通用装配
  it("无列声明 colNN", () => {
    expect(legacySampleToData(undefined, [1787000000000, 5, 6])).toEqual({ col1: 5, col2: 6 });
  });

  // 列数少于采样值 → 多余值用 colNN 通用装配
  it("列数少于采样值，多余列用 colNN 装配", () => {
    expect(legacySampleToData(namelessCols("a"), [1787000000000, 1, 2, 3])).toEqual({
      a: { percent: 1 },
      col2: 2,
      col3: 3,
    });
  });

  // 列数多于采样值 → 缺的跳过
  it("列数多于采样值，缺列跳过", () => {
    expect(legacySampleToData(namelessCols("a", "b", "c"), [1787000000000, 1])).toEqual({
